6: /**
7:  * Tienda en memoria de productos + suscripción "en vivo".
8:  *
9:  * El catálogo se carga UNA vez (o se refresca cuando algo cambia) y se comparte
10:  * entre pantallas. Así, al navegar entre secciones no se vuelve a mostrar
11:  * "Cargando…" ni se descarga todo de nuevo, y cualquier venta/compra que
12:  * cambie el stock se refleja al instante en TODAS las pantallas.
13:  *
14:  * Requisito: la tabla `productos` debe estar en la publicación de Supabase
15:  * Realtime (ver supabase/realtime.sql).
16:  */
17: 
18: type Listener = () => void
19: 
20: const PRODUCTS_CACHE_KEY = 'bodega:products-cache:v1'
21: 
22: function readPersistedCache(): ProductosRow[] | null {
23:   try {
24:     const raw = localStorage.getItem(PRODUCTS_CACHE_KEY)
25:     if (!raw) return null
26:     const parsed = JSON.parse(raw) as { products: ProductosRow[] }
27:     if (!Array.isArray(parsed?.products)) return null
28:     return parsed.products
29:   } catch {
30:     return null
31:   }
32: }
33: 
34: function persistCache(products: ProductosRow[]): void {
35:   try {
36:     localStorage.setItem(
37:       PRODUCTS_CACHE_KEY,
38:       JSON.stringify({ products, savedAt: Date.now() }),
39:     )
40:   } catch {
41:     // almacenamiento lleno o bloqueado: no es crítico
42:   }
43: }
44: 
45: let cache: ProductosRow[] | null = readPersistedCache()
46: let errorState: string | null = null
47: let inFlight: Promise<void> | null = null
48: let queuedForce = false
49: let channel: RealtimeChannel | null = null
50: let refreshTimer: number | null = null
51: const listeners = new Set<Listener>()
52: 
53: function sortByName(products: ProductosRow[]): ProductosRow[] {
54:   return [...products].sort((a, b) => a.nombre.localeCompare(b.nombre, 'es'))
55: }
56: 
57: function notify(): void {
58:   for (const listener of Array.from(listeners)) {
59:     listener()
60:   }
61: }
62: 
63: async function fetcher(): Promise<void> {
64:   const data = await fetchProducts()
65:   cache = sortByName(data)
66:   errorState = null
67:   persistCache(cache)
68: }
69: 
70: async function load(): Promise<void> {
71:   const force = queuedForce
72:   queuedForce = false
73: 
74:   if (inFlight) {
75:     if (!force) {
76:       await inFlight
77:       return
78:     }
79:     // Refresco forzado: aunque haya una carga en curso, encadena OTRO viaje a la
80:     // base de datos para que el nuevo stock se vea al instante.
81:     const current = inFlight
82:     inFlight = (async () => {
83:       try {
84:         await current
85:       } catch {
86:         // se ignora: abajo se lanza el nuevo viaje
87:       }
88:       await fetcher()
89:     })()
90:   } else {
91:     inFlight = fetcher()
92:   }
93: 
94:   try {
95:     await inFlight
96:   } catch (cause) {
97:     if (cache === null) {
98:       errorState =
99:         cause instanceof Error ? cause.message : 'Error al cargar los productos'
100:     }
101:   } finally {
102:     inFlight = null
103:     notify()
104:   }
105: }
106: 
107: function ensureChannel(): void {
108:   if (channel) return
109:   channel = supabase
110:     .channel('productos-en-vivo')
111:     .on(
112:       'postgres_changes',
113:       { event: '*', schema: 'public', table: 'productos' },
114:       () => {
115:         if (refreshTimer) {
116:           window.clearTimeout(refreshTimer)
117:         }
118:         refreshTimer = window.setTimeout(() => {
119:           void load()
120:         }, 400)
121:       },
122:     )
123:     .subscribe()
124: }
125: 
126: export function getProductsCache(): {
127:   products: ProductosRow[] | null
128:   error: string | null
129: } {
130:   return { products: cache, error: errorState }
131: }
132: 
133: export function subscribeToProducts(listener: Listener): () => void {
134:   listeners.add(listener)
135:   return () => {
136:     listeners.delete(listener)
137:   }
138: }
139: 
140: export function ensureProductsLoaded(): void {
141:   if (cache === null) {
142:     void load()
143:   }
144:   ensureChannel()
145: }
146: 
147: export function refreshProductsCache(force = false): void {
148:   if (force) {
149:     queuedForce = true
150:   }
151:   void load()
152: }
153: 
154: /**
155:  * Actualiza el stock en memoria al instante (sin esperar a la red) tras una
156:  * venta, para que el producto agotado desaparezca de la pantalla al momento.
157:  */
158: export function applyStockChanges(
159:   changes: { id: string; stockActual: number }[],
160: ): void {
161:   if (cache === null) return
162:   cache = sortByName(
163:     cache.map((product) => {
164:       const change = changes.find((item) => item.id === product.id)
165:       return change ? { ...product, stock_actual: change.stockActual } : product
166:     }),
167:   )
168:   persistCache(cache)
169:   notify()
170: }

