300: function createStackedPlanesBufferGeometry(
301:   n: number,
302:   width: number,
303:   height: number,
304:   spacing: number,
305:   heightSegments: number,
306: ): THREE.BufferGeometry {
307:   const geometry = new THREE.BufferGeometry()
308:   const numVertices = n * (heightSegments + 1) * 2
309:   const numFaces = n * heightSegments * 2
310:   const positions = new Float32Array(numVertices * 3)
311:   const indices = new Uint32Array(numFaces * 3)
312:   const uvs = new Float32Array(numVertices * 2)
313: 
314:   let vertexOffset = 0
315:   let indexOffset = 0
316:   let uvOffset = 0
317:   const totalWidth = n * width + (n - 1) * spacing
318:   const xOffsetBase = -totalWidth / 2
319: 
320:   for (let i = 0; i < n; i++) {
321:     const xOffset = xOffsetBase + i * (width + spacing)
322:     const uvXOffset = Math.random() * 300
323:     const uvYOffset = Math.random() * 300
324: 
325:     for (let j = 0; j <= heightSegments; j++) {
326:       const y = height * (j / heightSegments - 0.5)
327:       const v0 = [xOffset, y, 0]
328:       const v1 = [xOffset + width, y, 0]
329:       positions.set([...v0, ...v1], vertexOffset * 3)
330: 
331:       const uvY = j / heightSegments
332:       uvs.set([uvXOffset, uvY + uvYOffset, uvXOffset + 1, uvY + uvYOffset], uvOffset)
333: 
334:       if (j < heightSegments) {
335:         const a = vertexOffset,
336:           b = vertexOffset + 1,
337:           c = vertexOffset + 2,
338:           d = vertexOffset + 3
339:         indices.set([a, b, c, c, b, d], indexOffset)
340:         indexOffset += 6
341:       }
342:       vertexOffset += 2
343:       uvOffset += 4
344:     }
345:   }
346: 
347:   geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
348:   geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2))
349:   geometry.setIndex(new THREE.BufferAttribute(indices, 1))
350:   geometry.computeVertexNormals()
351:   return geometry
352: }
353: 
354: const MergedPlanes = forwardRef<
355:   THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
356:   {
357:     material: THREE.ShaderMaterial
358:     width: number
359:     count: number
360:     height: number
361:   }
362: >(({ material, width, count, height }, ref) => {
363:   const mesh = useRef<THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>>(
364:     null!,
365:   )
366:   useImperativeHandle(ref, () => mesh.current)
367:   const geometry = useMemo(
368:     () => createStackedPlanesBufferGeometry(count, width, height, 0, 100),
369:     [count, width, height],
370:   )
371:   useFrame((_, delta) => {
372:     mesh.current.material.uniforms.time.value += 0.1 * delta
373:   })
374:   return <mesh ref={mesh} geometry={geometry} material={material} />
375: })
376: MergedPlanes.displayName = 'MergedPlanes'
