30: create or replace function public.registrar_venta(p_articulos json, p_metodo_pago text default 'Efectivo')
31: returns json
32: language plpgsql
33: security definer
34: set search_path = public
35: as $$
36: declare
37:   v_venta_id uuid;
38:   v_item json;
39:   v_producto_id uuid;
40:   v_cantidad integer;
41:   v_precio numeric(12, 2);
42:   v_costo numeric(12, 2);
43:   v_subtotal numeric(12, 2);
44:   v_total numeric(12, 2) := 0;
45:   v_stock_actual integer;
46: begin
47:   if not public.es_miembro() then
48:     raise exception 'No autorizado';
49:   end if;
50: 
51:   insert into public.ventas (total, metodo_pago)
52:   values (0, coalesce(p_metodo_pago, 'Efectivo'))
53:   returning id into v_venta_id;
54: 
55:   for v_item in select * from json_array_elements(p_articulos)
56:   loop
57:     v_producto_id := (v_item ->> 'producto_id')::uuid;
58:     v_cantidad := (v_item ->> 'cantidad')::integer;
59:     v_precio := (v_item ->> 'precio_unitario')::numeric(12, 2);
60: 
61:     select stock_actual, costo into v_stock_actual, v_costo
62:     from public.productos
63:     where id = v_producto_id
64:     for update;
65: 
66:     if not found then
67:       raise exception 'El producto no existe (id: %)', v_producto_id;
68:     end if;
69: 
70:     if v_stock_actual < v_cantidad then
71:       raise exception 'Stock insuficiente para el producto (id: %, disponible: %)', v_producto_id, v_stock_actual;
72:     end if;
73: 
74:     v_subtotal := v_precio * v_cantidad;
75:     v_total := v_total + v_subtotal;
