399: -- ---------------------------------------------------------------------------
400: create or replace function public.dashboard_resumen()
401: returns json
402: language plpgsql
403: security definer
404: set search_path = public
405: as $$
406: declare
407:   v_hoy timestamptz;
408:   v_inicio_mes timestamptz;
409:   v_ventas_hoy numeric(12, 2);
410:   v_conteo_hoy integer;
411:   v_efectivo numeric(12, 2);
412:   v_yape numeric(12, 2);
413:   v_plin numeric(12, 2);
414:   v_gasto_mes numeric(12, 2);
415:   v_ganancia_hoy numeric(12, 2);
416:   v_total_productos integer;
417:   v_bajos integer;
418:   v_agotados integer;
419: begin
420:   if not public.es_miembro() then
421:     raise exception 'No autorizado';
422:   end if;
423: 
424:   v_hoy := date_trunc('day', now() at time zone 'America/Lima') at time zone 'America/Lima';
425:   v_inicio_mes := date_trunc('month', now() at time zone 'America/Lima') at time zone 'America/Lima';
426: 
427:   select coalesce(sum(v.total), 0), count(*)
428:     into v_ventas_hoy, v_conteo_hoy
429:   from public.ventas v
430:   where v.fecha >= v_hoy;
431: 
432:   select coalesce(sum(total), 0) into v_efectivo from public.ventas where fecha >= v_hoy and metodo_pago = 'Efectivo';
433:   select coalesce(sum(total), 0) into v_yape from public.ventas where fecha >= v_hoy and metodo_pago = 'Yape';
434:   select coalesce(sum(total), 0) into v_plin from public.ventas where fecha >= v_hoy and metodo_pago = 'Plin';
435: 
436:   select coalesce(sum(costo_total), 0)
437:     into v_gasto_mes
438:   from public.ingresos_mercaderia
439:   where fecha >= v_inicio_mes and cantidad_ingresada > 0;
440: 
441:   select coalesce(sum(v.total - coalesce(d.costo_unitario, p.costo) * d.cantidad), 0)
442:     into v_ganancia_hoy
443:   from public.ventas v
444:   join public.detalle_ventas d on d.venta_id = v.id
445:   left join public.productos p on p.id = d.producto_id
446:   where v.fecha >= v_hoy;
447: 
448:   select count(*) into v_total_productos from public.productos;
449:   select count(*) into v_bajos from public.productos where stock_actual <= stock_minimo;
450:   select count(*) into v_agotados from public.productos where stock_actual <= 0;
451: 
452:   return json_build_object(
453:     'ventas_hoy_total', v_ventas_hoy,
454:     'ventas_hoy_count', v_conteo_hoy,
455:     'efectivo_hoy', v_efectivo,
456:     'yape_hoy', v_yape,
457:     'plin_hoy', v_plin,
458:     'gasto_compras_mes', v_gasto_mes,
459:     'ganancia_estimada_hoy', v_ganancia_hoy,
460:     'total_productos', v_total_productos,
461:     'bajos_stock', v_bajos,
462:     'agotados', v_agotados
463:   );
464: end;
465: $$;
